#include <stdio.h>
void rs14_init(void); int rs14_reserve(unsigned*, unsigned*); int rs14_commit(unsigned, unsigned, unsigned); int rs14_abort(unsigned, unsigned); int rs14_read(unsigned, unsigned, unsigned*); unsigned rs14_digest(void);
int main(void){unsigned s0=0,g0=0,s1=0,g1=0,s2=0,g2=0,s3=0,g3=0,v=0,o=0,r=0,h=0;rs14_init();(void)rs14_reserve(&s0,&g0);rs14_commit(s0,g0,24u)?(o++):(r++);(void)rs14_reserve(&s1,&g1);rs14_abort(s1,g1)?(o++):(r++);(void)rs14_reserve(&s2,&g2);rs14_commit(s2,g2,40u)?(o++):(r++);(void)rs14_reserve(&s3,&g3);rs14_commit(s3,g3,48u)?(o++):(r++);(void)rs14_reserve(&s1,&g1);rs14_commit(s1,g1,64u)?(o++):(r++);(void)rs14_reserve(&s2,&g2);rs14_abort(s2,g2)?(o++):(r++); if(rs14_read(s0,g0,&v)){o++;h=(h*173u)^v;}else r++; if(rs14_read(s1,g1-1u,&v)){o++;h=(h*173u)^v;}else r++; if(rs14_read(s1,g1,&v)){o++;h=(h*173u)^v;}else r++; if(rs14_read(s2,g2-1u,&v)){o++;h=(h*173u)^v;}else r++; if(rs14_read(s2,g2,&v)){o++;h=(h*173u)^v;}else r++; if(rs14_read(s3,g3,&v)){o++;h=(h*173u)^v;}else r++; printf("%u %u %u %u\n",o,r,h,rs14_digest()); return 0; }
